Arr<float> packet_amp(const ItemEffectState& s, const Owned& own, const Ctx& ctx, const Units& u,
                      const Packets& p) {
    LS_PROF("items.packet_amp");
    const size_t c = ctx.unit.size(), n = u.x.size(), P = size(p);
    Arr<float> amp(c * n, 0.f);
    if (run(own, "mage", 6, s.mage, &ItemEffectState::mage)) {
        LS_PROF("items.mage.dealt_amp");
        Arr<float> a = ::lanesim::items::mage::dealt_amp(s.mage, own, ctx, u);
        for (size_t k = 0; k < c * n; ++k) amp[k] = amp[k] + a[k];
    }
    if (run(own, "marksman", 7, s.marksman, &ItemEffectState::marksman)) {
        LS_PROF("items.marksman.dealt_amp");
        Arr<float> a = ::lanesim::items::marksman::dealt_amp(s.marksman, own, ctx, u);
        for (size_t k = 0; k < c * n; ++k) amp[k] = amp[k] + a[k];
    }
    if (run(own, "boots", 8, s.boots, &ItemEffectState::boots)) {
        LS_PROF("items.boots.dealt_amp");
        Arr<float> a = ::lanesim::items::boots::dealt_amp(s.boots, own, ctx, u);
        for (size_t k = 0; k < c * n; ++k) amp[k] = amp[k] + a[k];
    }
    Arr<float> out(P, 0.f);
    for (size_t i = 0; i < P; ++i) {
        float sum = 0.f;
        int dst = clampi(p.dst[i], 0, (int)n - 1);
        for (size_t h = 0; h < c; ++h) sum = sum + (p.src[i] == ctx.unit[h] ? amp[h * n + dst] : 0.f);
        out[i] = sum;
    }
    if (run(own, "fighter", 4, s.fighter, &ItemEffectState::fighter)) {
        LS_PROF("items.fighter.packet_amp");
        Arr<float> a = ::lanesim::items::fighter::packet_amp(s.fighter, own, ctx, u, p);
        for (size_t i = 0; i < P; ++i) out[i] = out[i] + a[i];
    }
    if (run(own, "marksman", 7, s.marksman, &ItemEffectState::marksman)) {
        LS_PROF("items.marksman.packet_amp");
        Arr<float> a = ::lanesim::items::marksman::packet_amp(s.marksman, own, ctx, u, p);
        for (size_t i = 0; i < P; ++i) out[i] = out[i] + a[i];
    }
    if (run(own, "actives", 9, s.actives, &ItemEffectState::actives)) {
        LS_PROF("items.actives.packet_amp");
        Arr<float> a = ::lanesim::items::actives::packet_amp(s.actives, own, ctx, u, p);
        for (size_t i = 0; i < P; ++i) out[i] = out[i] + a[i];
    }
    return out;
}

