Effects active(ItemEffectState& s, const Owned& own, const Ctx& ctx, const Units& u, const Arr<int32_t>& request,
               ActiveOut& out) {
    LS_PROF("items.active");
    size_t c = ctx.unit.size();
    out.used.assign(c, 0), out.cast_time.assign(c, 0.f), out.can_move.assign(c, 1), out.attack_reset.assign(c, 0);
    Effects eff_all = no_effects((int)c, (int)u.x.size());
    if (run(own, "consumables", 0, s.consumables, &ItemEffectState::consumables)) {
        LS_PROF("items.consumables.active");
        auto [st, eff, r] = ::lanesim::items::consumables::active(std::move(s.consumables), own, ctx, u, request);
        s.consumables = std::move(st);
        merge_into(eff_all, eff);
        for (size_t h = 0; h < c; ++h) {
            if (r.used[h]) out.cast_time[h] = r.cast_time[h], out.can_move[h] = r.can_move[h];
            out.used[h] = out.used[h] | r.used[h], out.attack_reset[h] = out.attack_reset[h] | r.attack_reset[h];
        }
    }
    if (run(own, "hydra", 3, s.hydra, &ItemEffectState::hydra)) {
        LS_PROF("items.hydra.active");
        auto [st, eff, r] = ::lanesim::items::hydra::active(std::move(s.hydra), own, ctx, u, request);
        s.hydra = std::move(st);
        merge_into(eff_all, eff);
        for (size_t h = 0; h < c; ++h) {
            if (r.used[h]) out.cast_time[h] = r.cast_time[h], out.can_move[h] = r.can_move[h];
            out.used[h] = out.used[h] | r.used[h], out.attack_reset[h] = out.attack_reset[h] | r.attack_reset[h];
        }
    }
    if (run(own, "actives", 9, s.actives, &ItemEffectState::actives)) {
        LS_PROF("items.actives.active");
        auto [st, eff, r] = ::lanesim::items::actives::active(std::move(s.actives), own, ctx, u, request);
        s.actives = std::move(st);
        merge_into(eff_all, eff);
        for (size_t h = 0; h < c; ++h) {
            if (r.used[h]) out.cast_time[h] = r.cast_time[h], out.can_move[h] = r.can_move[h];
            out.used[h] = out.used[h] | r.used[h], out.attack_reset[h] = out.attack_reset[h] | r.attack_reset[h];
        }
    }
    return eff_all;
}

